<script setup lang="ts">import { ref } from 'vue'; const items=ref([{name:'洗衣凝珠',category:'日用品',done:false},{name:'牛奶',category:'食材',done:false},{name:'烧烤木炭',category:'露营',done:false}]);function toggle(index:number){items.value[index].done=!items.value[index].done}</script>
<template><view class="page"><view class="heading"><text class="label">买东西</text><text class="title">下次去超市，带上它们</text><text class="subtitle">想买不着急的，都放在购物袋里</text></view><view class="bag">🛍️　购物袋里有 {{items.filter((item)=>!item.done).length}} 件待买</view><view v-for="(item,index) in items" :key="item.name" class="item" @tap="toggle(index)"><text class="box" :class="{done:item.done}">{{item.done?'✓':' '}}</text><view><text class="item-name" :class="{cross:item.done}">{{item.name}}</text><text class="category">{{item.category}}</text></view></view><view class="new" @tap="uni.showToast({title:'新增购物项将在下一步接入',icon:'none'})">＋ 添加想买的东西</view></view></template>
<style scoped>.page{min-height:100vh;padding:38rpx 28rpx;background:#eef4fd}.heading .label,.heading .title,.heading .subtitle,.item-name,.category{display:block}.label{font-size:24rpx;letter-spacing:3rpx;color:#758aa7}.title{margin-top:10rpx;font-size:40rpx;font-weight:700;color:#465a79}.subtitle{margin-top:10rpx;font-size:23rpx;color:#8997ac}.bag{margin-top:30rpx;padding:25rpx;border-radius:24rpx;background:#dce9fc;color:#54739f;font-size:26rpx}.item{display:flex;align-items:center;gap:18rpx;margin-top:16rpx;padding:24rpx;border-radius:23rpx;background:#fffdfb}.box{display:flex;align-items:center;justify-content:center;width:37rpx;height:37rpx;border:2rpx solid #a5b8d4;border-radius:12rpx;color:white}.box.done{background:#75a984;border-color:#75a984}.item-name{font-size:29rpx;color:#4d5870}.cross{text-decoration:line-through;color:#a9b1bf}.category{margin-top:6rpx;font-size:21rpx;color:#9aa5b8}.new{margin-top:30rpx;padding:27rpx;border-radius:24rpx;background:#769fda;color:white;text-align:center;font-size:27rpx}</style>
